        left, right = obj["left"], obj["right"]
        occupied = {(y, x) for y, x in obj["cells"]}
        exterior = set()
        stack = []
        for y in range(top, bottom + 1):
            for x in range(left, right + 1):
                if (y, x) not in occupied and (
                    y == top or y == bottom or x == left or x == right
                ):
