                    stack.append((y, x))
        while stack:
            y, x = stack.pop()
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if (top <= ny <= bottom and left <= nx <= right and
                        (ny, nx) not in occupied and (ny, nx) not in exterior):
                    exterior.add((ny, nx))
                    stack.append((ny, nx))
        obj["to_top"] = any(
            (y, x) not in occupied and (y, x) not in exterior
            for y in range(top, bottom + 1)
            for x in range(left, right + 1)
        )

    out = [[0] * w for _ in range(h)]
