        return all(
            not (0 <= y < h and 0 <= x < w and out[y][x] != 0)
            for y, x in shifted
        )

    # Pack top-bound objects from the top, and bottom-bound objects from
    # the bottom, keeping their horizontal positions.
    for to_top in (True, False):
        group = [o for o in objects if o["to_top"] == to_top]
        if to_top:
            group.sort(key=lambda o: (o["top"], o["left"]))
        else:
            group.sort(key=lambda o: (-o["bottom"], o["left"]))

        for obj in group:
            height = obj["bottom"] - obj["top"] + 1
            positions = range(h - height + 1) if to_top else range(h - height, -1, -1)
            chosen = None
            for new_top in positions:
                if can_place(obj, new_top):
                    chosen = new_top
                    break
            if chosen is None:
